solution.solution.cpp:
// Keeps value within [low, high].
void clampInPlace(int& value, int low, int high)
{
    if (value < low) value = low;
    else if (value > high) value = high;
}

// Afterwards a <= b.
void orderPair(int& a, int& b)
{
    if (a > b)
    {
        const int old{ a };
        a = b;
        b = old;
    }
}

unitTests:
TEST("clamp below") { int v{ -5 }; clampInPlace(v, 0, 100); CHECK_EQ(v, 0); }
TEST("clamp above") { int v{ 250 }; clampInPlace(v, 0, 100); CHECK_EQ(v, 100); }
TEST("clamp inside") { int v{ 42 }; clampInPlace(v, 0, 100); CHECK_EQ(v, 42); }
TEST("order swaps when needed") { int a{ 9 }, b{ 3 }; orderPair(a, b); CHECK_EQ(a, 3); CHECK_EQ(b, 9); }
TEST("order leaves sorted pairs alone") { int a{ 1 }, b{ 2 }; orderPair(a, b); CHECK_EQ(a, 1); CHECK_EQ(b, 2); }
TEST("order with equal values") { int a{ 4 }, b{ 4 }; orderPair(a, b); CHECK_EQ(a, 4); CHECK_EQ(b, 4); }

